async function reservationsPage(){const [list,beats,profiles,waitlist]=await Promise.all([service.listReservations(state.user),service.listBeats({}),service.listProfiles(),service.listWaitlist?service.listWaitlist(state.user):Promise.resolve([])]);const byBeat=id=>beats.find(b=>b.id===id)||{title:'Production supprimée',coverClass:'cover-a',producer_name:'—'};const cards=list.length?list.map(r=>{const b=byBeat(r.beat_id),artist=profileById(profiles,r.artist_id),maker=profileById(profiles,r.beatmaker_id),canDecide=isAdmin()||state.user.id===r.beatmaker_id,active=r.status==='En discussion';return `<article class="reservation-row reservation-v5"><span class="mini-cover ${b.coverClass||'cover-a'}" style="${productionCoverStyle(b)}"></span><div class="reservation-main"><strong>${esc(b.title)}</strong><span>${esc(artist.name)} → ${esc(maker.name)}</span><small>Licence ${esc(r.license_name)} · ${dateShort(r.created_at)}</small>${active&&r.expires_at?`<small class="reservation-countdown" data-expires-at="${esc(r.expires_at)}">${esc(countdownLabel(r.expires_at))}</small>`:''}${r.decision_reason?`<small>Motif : ${esc(r.decision_reason)}</small>`:''}</div><span class="status ${statusClass(r.status)}">${esc(r.status)}</span><div class="reservation-actions"><a class="btn subtle small" href="#/app/messages/${r.conversation_id}">Conversation</a>${canDecide&&active?`<button class="btn subtle small" data-reservation-status="${r.id}" data-status="Acceptée">Accepter</button><button class="btn subtle small" data-reservation-status="${r.id}" data-status="Refusée">Refuser</button>`:''}${r.status==='Acceptée'&&canDecide?`<button class="btn primary small" data-beat-status="${b.id}" data-status="Expiré">Prise définitivement</button>`:''}${state.user.id===r.artist_id&&active?`<button class="btn danger-btn small" data-cancel-reservation="${r.id}">Annuler</button>`:''}</div></article>`}).join(''):'<div class="empty-state"><strong>Aucune réservation</strong><p>Les demandes apparaîtront ici.</p></div>';const wait=waitlist.length?`<section class="panel"><h3>Liste d’attente</h3>${waitlist.map(w=>{const b=w.beats||byBeat(w.beat_id);return `<div class="waitlist-row"><span class="mini-cover ${b?.cover_class||b?.coverClass||'cover-a'}" style="${productionCoverStyle({coverImage:b?.cover_image||b?.coverImage})}"></span><div><strong>${esc(b?.title||'Production')}</strong><small>Position ${w.position} · Licence ${esc(w.license_name)} · ${w.status==='notified'?'Disponible à nouveau':'En attente'}</small></div><a class="btn subtle small" href="#/beat/${esc(b?.slug||b?.id||w.beat_id)}">Voir</a></div>`}).join('')}</section>`:'';const body=`<div class="stack"><section class="manage-hero"><div><span class="badge">Réservations V5</span><h2>48 heures pour décider.</h2><p>Une seule réservation active par production. En cas de refus, d’annulation ou d’expiration, la production redevient disponible et la liste d’attente est avertie.</p></div></section><section class="reservation-list">${cards}</section>${wait}</div>`;return appShell('Réservations','Suivi des demandes et liste d’attente',body);}

function readReceiptLabel(value){if(!value)return'';const d=new Date(value),today=new Date();const same=d.toDateString()===today.toDateString();return same?`Vu à ${new Intl.DateTimeFormat('fr-FR',{hour:'2-digit',minute:'2-digit'}).format(d)}`:`Vu ${dateShort(d)}`;}
async function renderConversationMessages(current,profiles){const rows=[],messages=current?.messages||[];const sent=messages.filter(m=>m.sender_id===state.user.id&&m.type==='text');const lastSentId=sent.at(-1)?.id||'';for(const m of messages){const sender=profileById(profiles,m.sender_id);if(m.type==='reservation'||m.type==='reservation_status'){const payload=m.payload||{},beat=payload.beat_id?await service.getBeat(payload.beat_id):await service.getBeat(current.beat_id);const title=payload.title||beat?.title||'Production',cover=payload.cover_image||beat?.coverImage||'',coverClass=payload.cover_class||beat?.coverClass||'cover-a',status=payload.status||(m.type==='reservation'?'En discussion':'Mise à jour'),label=m.type==='reservation'?'Réservation automatique':'Mise à jour de la réservation';rows.push(`<div class="reservation-message reservation-status-block"><span class="reservation-block-cover ${coverClass}" style="${productionCoverStyle({coverImage:cover})}"></span><div><span class="eyebrow">${esc(label)}</span><h4>${esc(title)}</h4><p>${esc(payload.producer_name||beat?.producer_name||'Beatmaker')} · ${payload.bpm||beat?.bpm||'—'} BPM · ${esc(payload.key||beat?.key||'—')}</p><div class="chips"><span>${esc(payload.license_name||'Licence')}</span><span class="status ${statusClass(status)}">${esc(status)}</span></div>${payload.note?`<p>${esc(payload.note)}</p>`:''}${payload.reason?`<p class="decision-reason"><strong>Motif :</strong> ${esc(payload.reason)}</p>`:''}<a class="btn subtle small" href="#/beat/${payload.slug||beat?.slug||beat?.id||''}">Voir la production</a></div></div>`);continue;}if(m.type==='system'){rows.push(`<div class="system-message">${esc(m.text)}</div>`);continue;}const own=m.sender_id===state.user.id;const reads=(m.message_reads||[]).filter(r=>r.user_id!==state.user.id).sort((a,b)=>String(b.read_at).localeCompare(String(a.read_at)));const receipt=own&&m.id===lastSentId?(reads[0]?`<span class="message-read seen">✓✓ ${esc(readReceiptLabel(reads[0].read_at))}</span>`:'<span class="message-read">✓ Envoyé</span>'):'';rows.push(`<div class="message-wrap ${own?'sent':''}"><div class="message ${own?'sent':''}"><small>${esc(sender.name)}</small>${esc(m.text)}</div>${receipt}</div>`);}return rows.join('');}
async function messagesPage(id=''){
 const requestedId=String(id||'').trim();
 let conversations=await service.listConversations(state.user);
 let current=requestedId?await service.getConversation(state.user,requestedId):null;
 if(current&&!conversations.some(c=>c.id===current.id)){
  const last=(current.messages||[]).slice().sort((a,b)=>String(b.created_at).localeCompare(String(a.created_at)))[0]||null;
  conversations=[{...current,last_message:last},...conversations];
 }
 const currentId=requestedId||conversations[0]?.id||'';
 state.conversationId=currentId;
 state.pendingConversationId=currentId;
 state.currentProfiles=await service.listProfiles();
 state.profileLastSeen=new Map(state.currentProfiles.map(p=>[p.user_id,p.last_seen_at||'']));
 if(!current&&currentId)current=await service.getConversation(state.user,currentId);
 if(currentId&&document.visibilityState==='visible'){try{await service.markConversationRead(state.user,currentId);}catch(error){console.warn(error);}}
 state.currentConversation=current;
 const messageHtml=current?await renderConversationMessages(current,state.currentProfiles):'';
 const other=current?.members_profiles?.find(p=>p.user_id!==state.user.id)||current?.members_profiles?.[0];
 const body=`<div class="messages-layout"><aside class="conversation-list"><label class="search-box">${icon('search')}<input placeholder="Rechercher…"></label>${conversations.length?conversations.map(c=>{const p=c.members_profiles?.find(x=>x.user_id!==state.user.id)||c.members_profiles?.[0];return `<a class="conversation-item ${c.id===currentId?'active':''}" href="#/app/messages/${c.id}">${profileAvatar(p,'small')}<span><strong>${esc(c.title)}</strong><small>${esc(c.last_message?.text||'Nouvelle conversation')}</small></span><em>${timeAgo(c.updated_at)}</em></a>`}).join(''):'<div class="chat-empty">Aucune conversation</div>'}</aside><section class="chat">${current?`<header class="conversation-head">${profileAvatar(other,'small')}<div class="conversation-identity"><h2>${esc(current.title)}</h2><span class="presence-label ${isUserOnline(other?.user_id)?'online':''}" data-presence-text="${esc(other?.user_id||'')}">${esc(lastSeenLabel(other))}</span><span id="typing-indicator" class="typing-indicator"></span></div><a class="icon-btn" href="#/app/reservations">${icon('reserve')}</a></header><div class="chat-body">${messageHtml}</div><form id="chat-form" class="chat-form"><input name="message" required autocomplete="off" placeholder="Écrire un message…"><button class="icon-btn">${icon('send')}</button></form>`:`<div class="chat-empty"><span>${icon('message')}</span><strong>Sélectionne une conversation</strong><p>Les discussions restent disponibles après une acceptation, un refus, une annulation ou une expiration.</p></div>`}</section></div>`;
 return appShell('Messages','Conversations privées en temps réel',body);
}

